      t1 = kern::to<Int>(kern::formula([](Int k, Int a, Int a_2, Int a_3, Int e, Int f, Int g, Int a_4, Int a_5) -> Int { return kern::math::wrap32(kern::math::wrap32(kern::math::wrap32(kern::math::wrap32(k + kern::math::bxor(kern::math::bxor(a, a_2), a_3)) + kern::math::bxor(kern::math::band(e, f), kern::math::band(kern::math::wrap32(kern::math::bxor(e, -1.0)), g))) + a_4) + a_5); }, k, rotr(e, 6).Result, rotr(e, 11).Result, rotr(e, 25).Result, e, f, g, list_get<Int>(kK, n12.index), w[n12.index]));
