    nostr_Hasher s = nostr_Hasher{Fixed<Int, 8>{1779033703, 3144134277, 1013904242, 2773480762, 1359893119, 2600822924, 528734635, 1541459225}, Fixed<Int, 64>{}, 0, Int64{0x0}};
